errors = []   # (tabella, match_id, errore)

RAW_SCHEMA = StructType([
    StructField("match_id", StringType(), True),
    StructField("competition_id", StringType(), True),
    StructField("season_id", StringType(), True),
    StructField("payload", StringType(), True),   # un record JSON per riga
])

def bronze_path(name):
    return f"abfss://{adls_container_name}@{adls_account_name}/{bronze_root}/{name}"

def write_delta(df, name, mode="append", partition_cols=None):
    df = (df.withColumn("_ingested_at", F.current_timestamp())
            .withColumn("_source", F.lit("statsbombpy")))
    w = df.write.format("delta").mode(mode)
    if mode == "overwrite":
        w = w.option("overwriteSchema", "true")
    if partition_cols:
        w = w.partitionBy(*partition_cols)
    w.save(bronze_path(name))

def loaded_ids(name):
    """match_id già presenti nella tabella bronze (vuoto se la tabella non esiste ancora)."""
    path = bronze_path(name)
    if not DeltaTable.isDeltaTable(spark, path):
        return set()
    return {r.match_id for r in spark.read.format("delta").load(path).select("match_id").distinct().collect()}

def with_retry(fn, *args, tries=3, wait=2, **kwargs):
    for attempt in range(1, tries + 1):
        try:
            return fn(*args, **kwargs)
        except Exception:
            if attempt == tries:
                raise
            time.sleep(wait * attempt)

def _to_str(v):
    if v is None:
        return None
    try:
        if pd.isna(v):
            return None
    except (TypeError, ValueError):   # liste/array: non sono NaN
        pass
    return str(v)

def pandas_to_bronze_df(pdf):
    """Tabella piatta pandas -> Spark con tutte le colonne string (nessun errore di schema)."""
    pdf = pdf.astype(object).apply(lambda col: col.map(_to_str))
    schema = StructType([StructField(str(c), StringType(), True) for c in pdf.columns])
    return spark.createDataFrame(pdf.values.tolist(), schema=schema)

def to_json_lines(pdf):
    s = pdf.to_json(orient="records", lines=True, date_format="iso", force_ascii=False)
    return [l for l in s.split("\n") if l]

if run_matches:
