def ingest_per_match(name, fetch_fn, match_ids, batch):
    done = loaded_ids(name)
    todo = [m for m in match_ids if m not in done]
    print(f"[{name}] da caricare: {len(todo)} su {len(match_ids)}")

    def _safe(m):
        try:
            return with_retry(fetch_fn, m)
        except Exception as e:
            errors.append((name, m, repr(e)))
            return None

    for i in range(0, len(todo), batch):
        chunk = todo[i:i + batch]
        with ThreadPoolExecutor(max_workers=max_workers) as ex:
            results = list(ex.map(_safe, chunk))

        rows = []
        for m, lines in zip(chunk, results):
            if lines is not None:
                cid, sid = meta[m]
                rows.extend((m, cid, sid, l) for l in lines)

        if rows:
            write_delta(spark.createDataFrame(rows, schema=RAW_SCHEMA), name,
                        mode="append", partition_cols=["competition_id", "season_id"])
        print(f"[{name}] {min(i + batch, len(todo))}/{len(todo)} partite, {len(rows)} record scritti")

def fetch_lineups(m):
    out = []
    for team, pdf in sb.lineups(match_id=int(m)).items():
        pdf = pdf.copy()
        pdf["match_id"] = int(m)
        pdf["team"] = team
        out += to_json_lines(pdf)
    return out

def fetch_events(m):
    pdf = sb.events(match_id=int(m))
    pdf["match_id"] = int(m)
    return to_json_lines(pdf)

def fetch_frames(m):
    pdf = sb.frames(match_id=int(m), fmt="dataframe")
    pdf["match_id"] = int(m)
    return to_json_lines(pdf)

